    /*
     * Add to the DeviceModels
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	DeviceVendor
     */
    public DeviceVendor addToDeviceModels( UUID parentId, DeviceModel addTo ) {
	    LOGGER.info("handling AssignDeviceModelsToDeviceVendorEvent - " );
	    
	    DeviceVendor parentEntity = repository.findById(parentId).get();
	    DeviceModel child = registry.project( DeviceModel.class, addTo.getDeviceModelId());
	    
	    parentEntity.getDeviceModels().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

